import hmac
import hashlib
import struct
import time
import os
from flask import Flask, request, jsonify, session
from functools import wraps

app = Flask(__name__)
app.secret_key = os.urandom(32)

# Token configuration
TOKEN_SECRET = os.urandom(32)
TOKEN_LIFETIME = 3600  # 1 hour
MAX_FAILED_ATTEMPTS = 5
LOCKOUT_DURATION = 900  # 15 minutes

# In-memory user store with bcrypt-style hashing
import bcrypt

USERS = {}
FAILED_ATTEMPTS = {}

def create_user(username, password, role='user'):
    """Create user with bcrypt password hashing"""
    salt = bcrypt.gensalt(rounds=12)
    pw_hash = bcrypt.hashpw(password.encode('utf-8'), salt)
    USERS[username] = {'password_hash': pw_hash, 'role': role}

# Initialize default admin
create_user('admin', os.urandom(16).hex(), role='admin')

def generate_api_token(username, issued_at=None):
    """Generate time-limited API token.
    Token format: username|issued_timestamp|signature
    Uses HMAC-SHA256 for integrity.
    """
    if issued_at is None:
        issued_at = int(time.time())
    # Pack timestamp as unsigned 32-bit for compact representation
    ts_bytes = struct.pack('>I', issued_at & 0xFFFFFFFF)
    payload = username.encode('utf-8') + b'|' + ts_bytes
    sig = hmac.new(TOKEN_SECRET, payload, hashlib.sha256).digest()[:16]
    token = payload + b'|' + sig
    return token.hex()

def validate_api_token(token_hex):
    """Validate API token and check expiry.
    Returns (username, is_valid) tuple.
    """
    try:
        token = bytes.fromhex(token_hex)
    except (ValueError, TypeError):
        return None, False

    parts = token.split(b'|')
    if len(parts) != 3:
        return None, False

    username_bytes, ts_bytes, provided_sig = parts[0], parts[1], parts[2]

    # Reconstruct and verify signature
    payload = username_bytes + b'|' + ts_bytes
    expected_sig = hmac.new(TOKEN_SECRET, payload, hashlib.sha256).digest()[:16]

    if not hmac.compare_digest(provided_sig, expected_sig):
        return None, False

    # Verify token hasn't expired
    # Unpack as signed 32-bit to handle time arithmetic
    issued_at = struct.unpack('>i', ts_bytes)[0]
    current_time = int(time.time()) & 0xFFFFFFFF
    # Convert to signed for subtraction
    current_signed = struct.unpack('>i', struct.pack('>I', current_time))[0]

    elapsed = current_signed - issued_at

    if elapsed > TOKEN_LIFETIME:
        return None, False

    return username_bytes.decode('utf-8'), True

def check_lockout(username):
    """Check if account is locked out due to failed attempts"""
    if username not in FAILED_ATTEMPTS:
        return False
    attempts, lockout_time = FAILED_ATTEMPTS[username]
    if attempts >= MAX_FAILED_ATTEMPTS:
        if time.time() - lockout_time < LOCKOUT_DURATION:
            return True
        else:
            del FAILED_ATTEMPTS[username]
    return False

def record_failed_attempt(username):
    """Record a failed login attempt"""
    if username not in FAILED_ATTEMPTS:
        FAILED_ATTEMPTS[username] = (1, time.time())
    else:
        attempts, _ = FAILED_ATTEMPTS[username]
        FAILED_ATTEMPTS[username] = (attempts + 1, time.time())

def require_auth(f):
    """Decorator requiring valid API token or session"""
    @wraps(f)
    def decorated(*args, **kwargs):
        # Check API token first
        auth_header = request.headers.get('Authorization', '')
        if auth_header.startswith('Bearer '):
            token = auth_header[7:]
            username, valid = validate_api_token(token)
            if valid and username in USERS:
                request.current_user = username
                request.current_role = USERS[username]['role']
                return f(*args, **kwargs)

        # Fall back to session
        if 'user' in session and session['user'] in USERS:
            request.current_user = session['user']
            request.current_role = USERS[session['user']]['role']
            return f(*args, **kwargs)

        return jsonify({'error': 'Authentication required'}), 401
    return decorated

def require_admin(f):
    """Decorator requiring admin role"""
    @wraps(f)
    @require_auth
    def decorated(*args, **kwargs):
        if request.current_role != 'admin':
            return jsonify({'error': 'Admin access required'}), 403
        return f(*args, **kwargs)
    return decorated

@app.route('/api/login', methods=['POST'])
def login():
    """Authenticate user and return API token"""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request'}), 400

    username = data.get('username', '')
    password = data.get('password', '')

    if not username or not password:
        return jsonify({'error': 'Missing credentials'}), 400

    if check_lockout(username):
        return jsonify({'error': 'Account locked'}), 429

    if username not in USERS:
        # Constant-time comparison even for non-existent users
        bcrypt.hashpw(password.encode('utf-8'), bcrypt.gensalt(rounds=12))
        record_failed_attempt(username)
        return jsonify({'error': 'Invalid credentials'}), 401

    stored_hash = USERS[username]['password_hash']
    if bcrypt.checkpw(password.encode('utf-8'), stored_hash):
        # Clear failed attempts on success
        FAILED_ATTEMPTS.pop(username, None)
        token = generate_api_token(username)
        session['user'] = username
        return jsonify({'token': token, 'expires_in': TOKEN_LIFETIME})
    else:
        record_failed_attempt(username)
        return jsonify({'error': 'Invalid credentials'}), 401

@app.route('/api/profile', methods=['GET'])
@require_auth
def get_profile():
    """Get current user profile"""
    user = USERS[request.current_user]
    return jsonify({
        'username': request.current_user,
        'role': user['role']
    })

@app.route('/api/admin/users', methods=['GET'])
@require_admin
def list_users():
    """Admin endpoint to list all users"""
    return jsonify({
        'users': [{'username': u, 'role': d['role']} for u, d in USERS.items()]
    })

@app.route('/api/token/refresh', methods=['POST'])
@require_auth
def refresh_token():
    """Refresh API token"""
    new_token = generate_api_token(request.current_user)
    return jsonify({'token': new_token, 'expires_in': TOKEN_LIFETIME})

@app.after_request
def security_headers(response):
    """Apply security headers to all responses"""
    response.headers['X-Content-Type-Options'] = 'nosniff'
    response.headers['X-Frame-Options'] = 'DENY'
    response.headers['Content-Security-Policy'] = "default-src 'none'; frame-ancestors 'none'"
    response.headers['Strict-Transport-Security'] = 'max-age=31536000; includeSubDomains'
    response.headers['Cache-Control'] = 'no-store, no-cache, must-revalidate'
    response.headers['Pragma'] = 'no-cache'
    return response

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=5000)
